"""Extract both actual transports for same-machine native batch A/B."""
import json
import hashlib
import shutil
from pathlib import Path
from generate_ipc_transport_test import generate, FILES, ROOT
from generate_buffer_contract_test import method
from prepare_ipc_baseline import prepare
from prepare_ipc_pr6_before import prepare as prepare_before


def baseline(source,output):
    # Common OS adapters/disabled diagnostics come from the new fixture generator.
    generate(ROOT/'.deps/dxvk-remix',output)
    util=source/'bridge/src/util'
    hashes={}
    for name in FILES:
        if name=='data_ring_contract.h':continue
        text=(util/name).read_text(encoding='utf-8')
        hashes[name]=hashlib.sha256(text.encode()).hexdigest()
        if name=='util_ipcchannel.h':text=text.replace('#include "util_blockingcircularqueue.h"','')
        (output/name).write_text(text,encoding='utf-8')
    header=(util/'util_bridgecommand.h').read_text(encoding='utf-8')
    cpp=(util/'util_bridgecommand.cpp').read_text(encoding='utf-8')
    bridge=header[header.index('using namespace bridge_util;'):]
    bridge=bridge.replace('public:\n  static void init(','''public:
  static void install(WriterChannel* writer, ReaderChannel* reader) {
    s_pWriterChannel=writer;s_pReaderChannel=reader;s_cmdUID=0;
  }
  static void init(''',1)
    bodies=[]
    for marker in ('DECL_BRIDGE_FUNC(void, syncDataQueue,','DECL_BRIDGE_FUNC(Header, pop_front)',
                   'DECL_BRIDGE_FUNC(bridge_util::Result, waitForCommand,'):
        start,end=method(cpp,marker);bodies.append(cpp[start:end])
    prefix=cpp[cpp.index('namespace {'):cpp.index('DECL_BRIDGE_FUNC(void, init,')]
    definitions=cpp[cpp.index('#define DECL_COMMAND_FUNC'):]
    support=(ROOT/'tests/ipc_transport_support.h').read_text().replace('std::atomic<bool> gbBridgeRunning {true};','bool gbBridgeRunning=true;')
    server=(source/'bridge/src/server/main.cpp').read_text(encoding='utf-8')
    a=server.index('    *DeviceBridge::getReaderChannel().serverDataPos =');b=server.index('    const auto count = DeviceBridge::end_read_data();',a)
    complete='bool gOverwriteConditionAlreadyActive=false;\nvoid benchmarkComplete() {\n'+server[a:b]+'    DeviceBridge::end_read_data();\n}\n'
    complete=complete.replace('DeviceBridge::','Bridge<BridgeId::Device>::')
    generated='#define IPC_OLD_BASELINE\n'+support+'\n'+bridge+'\n'+prefix+'\n'+'\n'.join(bodies)+'\n'+definitions+'\n'+complete+'\n#include "ipc_performance_cases.cpp"\n'
    (output/'ipc_transport.cpp').write_text(generated,encoding='utf-8')
    hashes['util_bridgecommand.h']=hashlib.sha256(header.encode()).hexdigest()
    hashes['util_bridgecommand.cpp']=hashlib.sha256(cpp.encode()).hexdigest()
    hashes['server/main.cpp']=hashlib.sha256(server.encode()).hexdigest()
    (output/'source-manifest.json').write_text(json.dumps({'source_sha256':hashes,'scope':'actual old transport and exact Device consumption progress block'},indent=2)+'\n')

if __name__=='__main__':
    old=prepare()
    before=prepare_before()
    baseline(old,ROOT/'.deps/ipc-perf-A')
    generate(before,ROOT/'.deps/ipc-perf-B')
    current=ROOT/'.deps/dxvk-remix'
    generate(current,ROOT/'.deps/ipc-perf-C')
    # Attribution stages are actual checked implementations, not diagnostic
    # counters in the timed path. F isolates the local flag ordering; R adds
    # reservation reuse / cached acquired frontier; Q uses C's generic API.
    for variant,source in [('F',before),('R',current)]:
        staged=ROOT/f'.deps/ipc-stage-{variant}-source'
        util=staged/'bridge/src/util'
        shutil.copytree(source/'bridge/src/util',util,dirs_exist_ok=True)
        cpp=(util/'util_bridgecommand.cpp').read_text()
        if variant=='F':
            cpp=cpp.replace('pbCmdInProgress->load()', 'pbCmdInProgress->load(std::memory_order_relaxed)')
            cpp=cpp.replace('pbCmdInProgress->store(true)', 'pbCmdInProgress->store(true, std::memory_order_relaxed)')
            cpp=cpp.replace('pbCmdInProgress->store(false)', 'pbCmdInProgress->store(false, std::memory_order_relaxed)')
        else:
            shutil.copyfile(before/'bridge/src/util/util_atomiccircularqueue.h',util/'util_atomiccircularqueue.h')
            start=cpp.index('#ifndef USE_BLOCKING_QUEUE\n    m_status = s_pWriterChannel->commands->try_push(')
            end=cpp.index('    const auto configured =',start)
            cpp=cpp[:start]+cpp[end:]
            marker='budget, &gbBridgeRunning);\n    }\n'
            if cpp.count(marker)!=1:raise RuntimeError('Unexpected bounded finish layout')
            cpp=cpp.replace(marker,'budget, &gbBridgeRunning);\n',1)
        (util/'util_bridgecommand.cpp').write_text(cpp)
        generate(staged,ROOT/f'.deps/ipc-perf-{variant}')
    for variant in ('B','C','F','R'):
        p=ROOT/f'.deps/ipc-perf-{variant}/ipc_transport.cpp'
        code=p.read_text().replace('#include "ipc_transport_cases.cpp"','#include "ipc_performance_cases.cpp"')
        if variant=='C':code='#ifndef IPC_BENCH_GENERIC\n#define IPC_KNOWN_PACKET\n#endif\n'+code
        p.write_text(code)
    # Supplemental fidelity check: Command / out-of-line Bridge definitions
    # are compiled separately from the caller, as in the production project.
    # Preserve the original single-TU comparison rather than replacing it.
    for variant in ('A', 'B', 'C'):
        directory=ROOT/f'.deps/ipc-perf-{variant}'
        code=(directory/'ipc_transport.cpp').read_text()
        seam=code.index('\nnamespace {')
        header=code[:seam]
        running_type='bool' if variant=='A' else 'std::atomic<bool>'
        header=header.replace('std::atomic<bool> gbBridgeRunning {true};', 'extern std::atomic<bool> gbBridgeRunning;')
        header=header.replace('bool gbBridgeRunning=true;', 'extern bool gbBridgeRunning;')
        header=header.replace('std::atomic<bool> ipcInjectWaitFailure {false};', 'extern std::atomic<bool> ipcInjectWaitFailure;')
        header=header.replace('bridge_util::Guid gUniqueIdentifier;', 'extern bridge_util::Guid gUniqueIdentifier;')
        body=code[seam:code.index('#include "ipc_performance_cases.cpp"')]
        old_completion=''
        if variant=='A':
            split=body.index('bool gOverwriteConditionAlreadyActive')
            old_completion=body[split:]
            body=body[:split]
        (directory/'ipc_fixture.h').write_text('#pragma once\n'+header)
        globals=f'{running_type} gbBridgeRunning {{true}};\nstd::atomic<bool> ipcInjectWaitFailure {{false}};\nbridge_util::Guid gUniqueIdentifier;\n'
        (directory/'ipc_command.cpp').write_text('#include "ipc_fixture.h"\n'+globals+body)
        (directory/'ipc_caller.cpp').write_text('#include "ipc_fixture.h"\n'+old_completion+'\n#include "ipc_performance_cases.cpp"\n')
        manifest=directory/'source-manifest.json'
        metadata=json.loads(manifest.read_text())
        metadata['compilation_checks']=['original single translation unit', 'separate caller and Command translation units, no LTO']
        manifest.write_text(json.dumps(metadata,indent=2)+'\n')
